// SPDX-License-Identifier: MIT
pragma solidity ^0.8.7;
import "./IBEP20.sol";

contract Staking{
    event FundsWithdrawn(address owner,uint amount);
    event Staked(address owner,uint amount);

    struct stake{
        uint amount;
        address asset;
    }

    mapping (address=>stake) public Stakes;


    function stakeAsset(address asset,uint amount) external payable {
        require(IBEP20(asset).balanceOf(msg.sender) > amount ,"insufficient balance");
        IBEP20(asset).transferFrom(msg.sender, payable(address(this)), amount);
        Stakes[msg.sender] = stake(amount,asset);
        emit Staked(msg.sender,amount);
    }

    receive() external payable{}

    function withdraw(uint amount) external{
        stake storage userStake = Stakes[msg.sender];
        require(userStake.amount > 0,"you have no staked assets");
        userStake.amount = 0;
        IBEP20(userStake.asset).transferFrom(address(this),payable(msg.sender),amount);
        emit FundsWithdrawn(msg.sender,amount);
    }
}
